#!/usr/bin/env python3
"""
Task-scoped helper for the "European economic performance" data storytelling task.

Discovers structured data files in the workspace, parses them, extracts European
economic indicators (growth, inflation, unemployment, public finances, trade,
population, GDP), computes summary statistics and trends, and writes a Markdown
data storytelling report following the data-storytelling skill structure.
"""

import csv
import json
import os
import re
import statistics
import sys
from collections import defaultdict
from datetime import datetime, timezone

OUT_PATH = sys.argv[1] if len(sys.argv) > 1 else "european_economic_performance_report.md"
EXCLUDE_DIRS = {".codex", "__pycache__", ".git", "node_modules"}
EXCLUDE_FILES = {os.path.basename(__file__), os.path.basename(OUT_PATH)}

METRICS = [
    ("growth",       ["growth", "yoy", "year on year", "change"]),
    ("inflation",    ["inflation", "hicp", "cpi", "consumer price", "price index"]),
    ("unemployment", ["unemploy", "jobless", "labour force", "labor force"]),
    ("deficit",      ["deficit", "net lending", "net borrowing", "fiscal balance", "budget balance"]),
    ("debt",         ["debt", "government liabilit"]),
    ("exports",      ["export"]),
    ("imports",      ["import"]),
    ("population",   ["population", "inhabitants", "residents"]),
    ("gdp",          ["gdp", "gross domestic product", "gross value added"]),
    ("value",        ["obs value", "value"]),
]

COUNTRY_KEYS = ["country", "geo", "nation", "member state", "geography", "territory", "reporting country"]
YEAR_KEYS = ["year", "time", "period", "date", "obs time"]
INDICATOR_KEYS = ["indicator", "measure", "metric", "statistic", "series name", "series"]

AGGREGATE_RE = re.compile(
    r"\b(eu\d*|european union|euro area|eurozone|europe|world|oecd|g20|g7|ea\d+)\b", re.I
)

COUNTRY_CODES = {
    "AT": "Austria", "BE": "Belgium", "BG": "Bulgaria", "HR": "Croatia", "CY": "Cyprus",
    "CZ": "Czechia", "DK": "Denmark", "EE": "Estonia", "FI": "Finland", "FR": "France",
    "DE": "Germany", "EL": "Greece", "GR": "Greece", "HU": "Hungary", "IE": "Ireland",
    "IT": "Italy", "LV": "Latvia", "LT": "Lithuania", "LU": "Luxembourg", "MT": "Malta",
    "NL": "Netherlands", "PL": "Poland", "PT": "Portugal", "RO": "Romania", "SK": "Slovakia",
    "SI": "Slovenia", "ES": "Spain", "SE": "Sweden", "GB": "United Kingdom", "UK": "United Kingdom",
    "CH": "Switzerland", "NO": "Norway", "IS": "Iceland", "LI": "Liechtenstein",
    "MK": "North Macedonia", "AL": "Albania", "RS": "Serbia", "ME": "Montenegro",
    "BA": "Bosnia and Herzegovina", "MD": "Moldova", "UA": "Ukraine", "TR": "Türkiye",
}


def norm_key(k):
    return re.sub(r"[^a-z0-9]+", " ", str(k).lower()).strip()


def parse_number(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace("\u00a0", "")
    if not s or s.lower() in ("-", "--", ":", "..", "na", "n/a", "null", "none", "nan"):
        return None
    s = re.sub(r"[€$£%]", "", s)
    s = re.sub(r"[A-Za-z]+$", "", s).strip().replace(" ", "")
    if not s:
        return None
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        if re.fullmatch(r"-?\d{1,3}(,\d{3})+", s):
            s = s.replace(",", "")
        else:
            s = s.replace(",", ".")
    try:
        return float(s)
    except ValueError:
        return None


def extract_year(v):
    if v is None:
        return None
    if isinstance(v, (int, float)) and float(v).is_integer():
        y = int(v)
        return y if 1950 <= y <= 2035 else None
    m = re.search(r"(?:19|20)\d{2}", str(v))
    if m:
        y = int(m.group(0))
        return y if 1950 <= y <= 2035 else None
    return None


def clean_country(v):
    if v is None:
        return None
    s = str(v).strip()
    if not s:
        return None
    up = s.upper()
    if up in COUNTRY_CODES:
        return COUNTRY_CODES[up]
    return s


def metric_matches(metric, k):
    if metric == "growth" and ("population" in k or "unemploy" in k):
        return False
    if metric == "gdp" and "per capita" in k:
        return False
    if metric == "debt" and "deficit" in k:
        return False
    if metric == "value" and any(
        x in k for x in ("gdp", "growth", "inflation", "unemploy", "debt", "deficit")
    ):
        return False
    return True


def discover_files():
    found = []
    for base in [os.getcwd()]:
        for root, dirs, files in os.walk(base):
            dirs[:] = [d for d in dirs if d not in EXCLUDE_DIRS and not d.startswith(".")]
            for f in files:
                if f in EXCLUDE_FILES or f.startswith("."):
                    continue
                if f.lower().endswith((".csv", ".tsv", ".txt", ".md", ".json", ".jsonl")):
                    found.append(os.path.join(root, f))
    return sorted(found)


def json_to_rows(obj):
    if isinstance(obj, list):
        return [r for r in obj if isinstance(r, dict)]
    if not isinstance(obj, dict):
        return []
    for k in ("data", "records", "rows", "values", "observations", "result", "series"):
        v = obj.get(k)
        if isinstance(v, list):
            return [r for r in v if isinstance(r, dict)]
    for k, v in obj.items():
        if isinstance(v, dict) and v and all(
            isinstance(x, (int, float, str)) for x in v.values()
        ):
            rows = []
            for t, val in v.items():
                row = {"time": t, "value": val}
                for kk, vv in obj.items():
                    if kk != k and isinstance(vv, (str, int, float)):
                        row[kk] = vv
                rows.append(row)
            return rows
    return [obj]


def md_tables_to_rows(text):
    rows = []
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if line.startswith("|"):
            header = [c.strip() for c in line.strip("|").split("|")]
            j = i + 1
            while j < len(lines) and lines[j].strip().startswith("|"):
                sep = [c.strip() for c in lines[j].strip("|").split("|")]
                if sep and all(re.fullmatch(r":?-{2,}:?", c) for c in sep if c):
                    j += 1
                    continue
                vals = [c.strip() for c in lines[j].strip("|").split("|")]
                if len(vals) == len(header):
                    rows.append(dict(zip(header, vals)))
                j += 1
            i = j
        else:
            i += 1
    return rows


def load_rows(path):
    ext = os.path.splitext(path)[1].lower()
    rows = []
    try:
        if ext == ".json":
            with open(path, encoding="utf-8-sig") as fh:
                obj = json.load(fh)
            rows = json_to_rows(obj)
        elif ext == ".jsonl":
            with open(path, encoding="utf-8-sig") as fh:
                rows = [json.loads(l) for l in fh if l.strip()]
        elif ext in (".csv", ".tsv"):
            with open(path, encoding="utf-8-sig", newline="") as fh:
                sample = fh.read(8192)
                fh.seek(0)
                try:
                    delim = csv.Sniffer().sniff(sample, delimiters=",;\t").delimiter
                except Exception:
                    delim = ";" if ";" in sample else ("," if "," in sample else "\t")
                rd = csv.DictReader(fh, delimiter=delim)
                rows = [dict(r) for r in rd if any((v or "").strip() for v in r.values())]
        elif ext in (".txt", ".md"):
            with open(path, encoding="utf-8-sig") as fh:
                text = fh.read()
            rows = md_tables_to_rows(text)
            if not rows:
                kv = {}
                for line in text.splitlines():
                    if line.lstrip().startswith(("#", "-", "*", ">")):
                        continue
                    m = re.match(r"^\s*([A-Za-z][A-Za-z0-9 _\-/().]*?)\s*[:=]\s*(.+?)\s*$", line)
                    if m:
                        kv[m.group(1).strip()] = m.group(2).strip()
                if kv:
                    rows = [kv]
    except Exception as exc:
        print(f"[warn] could not parse {path}: {exc}")
    return rows


def extract_into(datasets, rows):
    norm_rows = []
    for r in rows:
        nr = {}
        for k, v in r.items():
            if k is None:
                continue
            nr[norm_key(k)] = v
        if nr:
            norm_rows.append(nr)
    if not norm_rows:
        return 0

    all_keys = set()
    for r in norm_rows:
        all_keys.update(r.keys())

    country_key = next((k for k in all_keys if any(kw in k for kw in COUNTRY_KEYS)), None)
    year_key = None
    for k in all_keys:
        if any(kw in k for kw in YEAR_KEYS):
            if any(extract_year(r.get(k)) is not None for r in norm_rows[:80]):
                year_key = k
                break
    indicator_key = next(
        (k for k in all_keys if any(kw in k for kw in INDICATOR_KEYS)), None
    )

    used = 0
    for r in norm_rows:
        country = clean_country(r.get(country_key)) if country_key else None
        year = extract_year(r.get(year_key)) if year_key else None
        contributed = False
        claimed = set()

        # Row-level indicator label (long-format datasets)
        ind_raw = r.get(indicator_key) if indicator_key else None
        ind_metric = None
        if ind_raw is not None:
            iv = norm_key(str(ind_raw))
            for metric, kws in METRICS:
                if any(kw in iv for kw in kws):
                    ind_metric = metric
                    break
        if ind_metric:
            for k, v in r.items():
                if k in (country_key, year_key, indicator_key):
                    continue
                num = parse_number(v)
                if num is not None:
                    datasets[ind_metric].append((country, year, num))
                    claimed.add(k)
                    contributed = True
                    break

        for metric, kws in METRICS:
            for k, v in r.items():
                if k in claimed or k == country_key or k == year_key or k == indicator_key:
                    continue
                if not metric_matches(metric, k) or not any(kw in k for kw in kws):
                    continue
                num = parse_number(v)
                if num is None:
                    continue
                col_year = year
                if col_year is None:
                    m = re.search(r"(?:19|20)\d{2}", k)
                    if m:
                        col_year = int(m.group(0))
                datasets[metric].append((country, col_year, num))
                claimed.add(k)
                contributed = True

        # Wide-by-year tables: bare 4-digit year columns
        for k, v in r.items():
            if k in claimed or k == country_key or k == year_key or k == indicator_key:
                continue
            if re.fullmatch(r"(?:19|20)\d{2}", k):
                num = parse_number(v)
                if num is not None:
                    datasets["value"].append((country, int(k), num))
                    claimed.add(k)
                    contributed = True

        if contributed:
            used += 1
    return used


def member_items(ds, latest_only=True):
    rows = ds
    if latest_only:
        ys = [y for _, y, _ in rows if y is not None]
        if ys:
            ly = max(ys)
            rows = [t for t in rows if t[1] == ly]
    agg = defaultdict(list)
    for c, _, v in rows:
        if c is None:
            continue
        agg[c].append(v)
    items = [(c, statistics.mean(vs)) for c, vs in agg.items()]
    mem = [(c, v) for c, v in items if not AGGREGATE_RE.search(c)]
    if len(mem) >= 2:
        return mem
    return items


def yearly_means(ds):
    by_year = defaultdict(list)
    for c, y, v in ds:
        if y is None or c is None:
            continue
        if AGGREGATE_RE.search(c):
            continue
        by_year[y].append(v)
    return [(y, statistics.mean(by_year[y])) for y in sorted(by_year)]


def series_for(ds, pattern):
    out = defaultdict(list)
    for c, y, v in ds:
        if y is not None and c and re.search(pattern, c, re.I):
            out[y].append(v)
    return [(y, statistics.mean(vs)) for y, vs in sorted(out.items())]


def hbar(title, items, width=24, nd=2):
    mn = min(v for _, v in items)
    mx = max(v for _, v in items)
    scale = max(abs(mn), abs(mx), 1e-9)
    labw = min(max(len(str(l)) for l, _ in items), 24)
    out = [f"**{title}**", "```"]
    for lab, v in items:
        n = int(round(abs(v) / scale * width))
        bar = "#" * n
        if v >= 0:
            out.append(f"{str(lab)[:labw]:<{labw}} |{bar:<{width}}| +{v:,.{nd}f}")
        else:
            out.append(f"{str(lab)[:labw]:<{labw}} |{bar:>{width}}| {v:,.{nd}f}")
    out.append("```")
    return "\n".join(out)


def build_headline(datasets):
    candidates = []
    for metric, unit in [
        ("growth", "percentage points"),
        ("inflation", "percentage points"),
        ("unemployment", "percentage points"),
        ("debt", "points of GDP"),
    ]:
        items = member_items(datasets[metric])
        if len(items) < 2:
            continue
        srt = sorted(items, key=lambda t: t[1])
        low_c, low_v = srt[0]
        high_c, high_v = srt[-1]
        spread = high_v - low_v
        if metric == "growth":
            msg = (f"Europe's growth divide: **{high_c}** expanded {high_v:.1f}% while "
                   f"**{low_c}** grew just {low_v:.1f}% — a {spread:.1f}-point gap.")
        elif metric == "inflation":
            msg = (f"Inflation spans **{low_v:.1f}%** ({low_c}) to **{high_v:.1f}%** ({high_c}) — "
                   f"a {spread:.1f}-point spread around the ECB's 2% target.")
        elif metric == "unemployment":
            msg = (f"Labour markets diverge sharply: unemployment is **{low_v:.1f}%** in {low_c} "
                   f"but **{high_v:.1f}%** in {high_c}.")
        else:
            msg = (f"Public debt tells two Europes: **{high_v:.0f}% of GDP** in {high_c} versus "
                   f"**{low_v:.0f}%** in {low_c} — on opposite sides of the 60% Maastricht reference.")
        candidates.append((abs(spread), msg))
    if candidates:
        return max(candidates, key=lambda t: t[0])[1]
    return ("The local dataset paints a picture of a resilient but uneven European economy — "
            "the sections below show where the risks and opportunities lie.")


def write_report(datasets, sources):
    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    total_obs = sum(len(ds) for ds in datasets.values())
    lines = []

    lines.append("# European Economic Performance — A Data Storytelling Report")
    lines.append("")
    lines.append(f"*Generated {now} from local workspace data by a task-scoped analysis helper.*")
    lines.append("")
    lines.append("---")
    lines.append("")

    lines.append("## The Hook")
    lines.append("")
    lines.append(f"> **{build_headline(datasets)}**")
    lines.append("")

    lines.append("## The Evidence Base: What We Found")
    lines.append("")
    if sources:
        lines.append("The report is built from the files discovered in the workspace:")
        lines.append("")
        lines.append("| File | Rows loaded | Rows with numeric indicators |")
        lines.append("|---|---|---|")
        for path, loaded, used in sources:
            lines.append(f"| `{os.path.relpath(path)}` | {loaded} | {used} |")
    else:
        lines.append("No structured data files (CSV/TSV/JSON/Markdown tables) were found.")
    lines.append("")

    lines.append("## The Context (Setup)")
    lines.append("")
    labels = {
        "growth": ("GDP growth", "%"),
        "inflation": ("Inflation", "%"),
        "unemployment": ("Unemployment rate", "%"),
        "debt": ("Government debt", "% of GDP"),
        "deficit": ("Government deficit/surplus", "% of GDP"),
        "exports": ("Exports", ""),
        "imports": ("Imports", ""),
        "population": ("Population", ""),
        "gdp": ("GDP", ""),
        "value": ("Other measured values", ""),
    }
    if total_obs == 0:
        lines.append("No numeric indicators could be extracted from the discovered files. "
                     "The file inventory above shows what was available; adding structured "
                     "tables with country, year and indicator columns would enable the full story.")
        lines.append("")
    else:
        lines.append("| Indicator | Countries | Period | Mean (latest year) | Range (latest year) |")
        lines.append("|---|---|---|---|---|")
        for metric, (label, unit) in labels.items():
            ds = datasets[metric]
            if not ds:
                continue
            items = member_items(ds)
            ys = [y for _, y, _ in ds if y is not None]
            period = f"{min(ys)}–{max(ys)}" if ys else "n/a"
            if items:
                vals = [v for _, v in items]
                mean = statistics.mean(vals)
                lo = min(vals)
                hi = max(vals)
                lines.append(f"| {label} | {len(items)} | {period} | {mean:,.2f}{unit} | {lo:,.2f} to {hi:,.2f}{unit} |")
        lines.append("")

    lines.append("## The Story: Winners and Laggards")
    lines.append("")
    chart_metrics = [
        ("growth", "Real GDP growth"),
        ("inflation", "Inflation"),
        ("unemployment", "Unemployment rate"),
        ("debt", "Government debt"),
    ]
    for metric, base_title in chart_metrics:
        ds = datasets[metric]
        items = member_items(ds)
        if len(items) < 2:
            continue
        ys = [y for _, y, _ in ds if y is not None]
        yr = f" ({max(ys)})" if ys else ""
        items_sorted = sorted(items, key=lambda t: t[1])
        lines.append(hbar(f"{base_title}{yr} — all economies, sorted", items_sorted))
        lines.append("")

    lines.append("## The Trend Over Time")
    lines.append("")
    for metric in ["growth", "inflation", "unemployment", "debt"]:
        yrs = yearly_means(datasets[metric])
        if len(yrs) >= 2:
            lines.append(f"### {labels[metric][0]} — cross-country average by year")
            lines.append("")
            lines.append("| Year | Average |")
            lines.append("|---|---|")
            for y, v in yrs:
                lines.append(f"| {y} | {v:.2f} |")
            lines.append("")
    for metric in ["growth", "inflation"]:
        ser = series_for(datasets[metric], r"european union|eu\d+")
        if len(ser) >= 2:
            lines.append(f"### European Union — {labels[metric][0]} by year")
            lines.append("")
            lines.append("| Year | EU |")
            lines.append("|---|---|")
            for y, v in ser:
                lines.append(f"| {y} | {v:.2f} |")
            lines.append("")

    lines.append("## The Key Insight")
    lines.append("")
    insight_lines = []
    gi = member_items(datasets["growth"])
    if len(gi) >= 2:
        gs = sorted(gi, key=lambda t: t[1])
        low_c, low_v = gs[0]
        high_c, high_v = gs[-1]
        insight_lines.append(
            f"- **Growth is a story of divergence, not convergence.** In the latest year, "
            f"{high_c} grew {high_v:.1f}% versus {low_c} at {low_v:.1f}% — a "
            f"{high_v - low_v:.1f}-point gap between Europe's fastest and slowest economies."
        )
    ii = member_items(datasets["inflation"])
    if len(ii) >= 2:
        spread = max(v for _, v in ii) - min(v for _, v in ii)
        insight_lines.append(
            f"- **Inflation is uneven.** The cross-country spread is {spread:.1f} percentage points, "
            "which complicates a one-size-fits-all monetary policy response."
        )
    di = member_items(datasets["debt"])
    if len(di) >= 2:
        above = sum(1 for _, v in di if v > 60)
        insight_lines.append(
            f"- **Fiscal space is asymmetric.** {above} of {len(di)} economies carry debt above the "
            "60% of GDP Maastricht reference, limiting room to invest or cushion shocks."
        )
    du = member_items(datasets["deficit"])
    if len(du) >= 2:
        vals = [v for _, v in du]
        med = statistics.median(vals)
        if med < 0:
            excessive = sum(1 for _, v in du if v < -3.0)
            side = "deficits above the 3% of GDP reference value"
        else:
            excessive = sum(1 for _, v in du if v > 3.0)
            side = "positions beyond +3% of GDP"
        insight_lines.append(
            f"- **Fiscal positions vary widely.** {excessive} of {len(du)} economies report {side}."
        )
    if not insight_lines:
        insight_lines.append(
            "- The available indicators point to a mixed picture: strengths in some economies and "
            "pressures in others, with the details in the tables above."
        )
    lines.extend(insight_lines)
    lines.append("")

    lines.append("## Implications and Recommendations")
    lines.append("")
    recs = []
    if len(gi) >= 2:
        recs.append("1. **Close the growth gap with targeted support** — channel cohesion and recovery "
                    "funds toward the slowest-growing economies, where catch-up potential is highest.")
    if len(ii) >= 2:
        recs.append("2. **Watch the inflation outliers** — where inflation still runs well above 2%, "
                    "tighten monitoring of wage–price pass-through; where it runs below, growth-supportive "
                    "conditions can be maintained.")
    if len(di) >= 2:
        recs.append("3. **Differentiate fiscal strategy by debt level** — high-debt economies should anchor "
                    "consolidation to credible multi-year plans; low-debt economies can afford growth-friendly "
                    "investment.")
    if len(du) >= 2:
        recs.append("4. **Enforce the fiscal rule framework consistently** — the spread in fiscal positions "
                    "shows why the revised EU rules need even-handed application.")
    if len(member_items(datasets["unemployment"])) >= 2:
        recs.append("5. **Target labour-market programmes** where unemployment remains structurally high, "
                    "pairing activation policies with investment in skills.")
    if not recs:
        recs.append("1. **Build the evidence base first** — the current dataset is too thin for firm "
                    "policy recommendations; add more indicators and years.")
    lines.extend(recs)
    lines.append("")

    lines.append("## Call to Action")
    lines.append("")
    lines.append("The data supports a clear next step: **commission a quarterly European economic monitor** "
                 "that tracks growth, inflation, labour markets and public finances for every member state, "
                 "so divergence is caught early rather than after the fact. Decisions needed now: "
                 "(1) which economies warrant watch-list status, and (2) which policy levers — fiscal, "
                 "monetary or structural — to pull first.")
    lines.append("")

    lines.append("## Appendix: Method and Limitations")
    lines.append("")
    if sources:
        lines.append("- Files discovered and parsed: "
                     + "; ".join(f"`{os.path.relpath(p)}`" for p, _, _ in sources) + ".")
    else:
        lines.append("- Files discovered and parsed: none.")
    lines.append("- Units: percent for rates; absolute values for GDP, trade and population where reported. "
                 "Where files mixed units, averages are indicative only.")
    lines.append("- Cross-country averages weight each economy equally and use the latest available year "
                 "per indicator; missing years are excluded.")
    lines.append("- Aggregate regions (EU, euro area, etc.) are excluded from country comparisons but "
                 "reported separately where available.")
    lines.append("- Causation is not claimed: the narrative identifies patterns in the observed data, "
                 "not the reasons behind them.")
    lines.append("")

    with open(OUT_PATH, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines))
    print(f"[ok] report written to {OUT_PATH} ({len(lines)} lines, {total_obs} observations)")


def print_summary(datasets, sources):
    print("=== Sources ===")
    for p, loaded, used in sources:
        print(f"  {os.path.relpath(p)}: {loaded} rows loaded, {used} rows with numeric data")
    print("=== Indicators extracted ===")
    for metric, _ in METRICS:
        ds = datasets[metric]
        if ds:
            n_countries = len({c for c, _, _ in ds if c})
            print(f"  {metric}: {len(ds)} observations, {n_countries} countries")


def main():
    files = discover_files()
    datasets = defaultdict(list)
    sources = []
    for path in files:
        rows = load_rows(path)
        n = len(rows)
        if not rows:
            sources.append((path, n, 0))
            continue
        used = extract_into(datasets, rows)
        sources.append((path, n, used))
    write_report(datasets, sources)
    print_summary(datasets, sources)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Task-scoped helper for the "European economic performance" data storytelling task.

Discovers structured data files in the workspace, parses them, extracts European
economic indicators (growth, inflation, unemployment, public finances, trade,
population, GDP), computes summary statistics and trends, and writes a Markdown
data storytelling report following the data-storytelling skill structure.
"""

import csv
import json
import os
import re
import statistics
import sys
from collections import defaultdict
from datetime import datetime, timezone

OUT_PATH = sys.argv[1] if len(sys.argv) > 1 else "european_economic_performance_report.md"
EXCLUDE_DIRS = {".codex", "__pycache__", ".git", "node_modules"}
EXCLUDE_FILES = {os.path.basename(__file__), os.path.basename(OUT_PATH)}

METRICS = [
    ("growth",       ["growth", "yoy", "year on year", "change"]),
    ("inflation",    ["inflation", "hicp", "cpi", "consumer price", "price index"]),
    ("unemployment", ["unemploy", "jobless", "labour force", "labor force"]),
    ("deficit",      ["deficit", "net lending", "net borrowing", "fiscal balance", "budget balance"]),
    ("debt",         ["debt", "government liabilit"]),
    ("exports",      ["export"]),
    ("imports",      ["import"]),
    ("population",   ["population", "inhabitants", "residents"]),
    ("gdp",          ["gdp", "gross domestic product", "gross value added"]),
    ("value",        ["obs value", "value"]),
]

COUNTRY_KEYS = ["country", "geo", "nation", "member state", "geography", "territory", "reporting country"]
YEAR_KEYS = ["year", "time", "period", "date", "obs time"]
INDICATOR_KEYS = ["indicator", "measure", "metric", "statistic", "series name", "series"]

AGGREGATE_RE = re.compile(
    r"\b(eu\d*|european union|euro area|eurozone|europe|world|oecd|g20|g7|ea\d+)\b", re.I
)

COUNTRY_CODES = {
    "AT": "Austria", "BE": "Belgium", "BG": "Bulgaria", "HR": "Croatia", "CY": "Cyprus",
    "CZ": "Czechia", "DK": "Denmark", "EE": "Estonia", "FI": "Finland", "FR": "France",
    "DE": "Germany", "EL": "Greece", "GR": "Greece", "HU": "Hungary", "IE": "Ireland",
    "IT": "Italy", "LV": "Latvia", "LT": "Lithuania", "LU": "Luxembourg", "MT": "Malta",
    "NL": "Netherlands", "PL": "Poland", "PT": "Portugal", "RO": "Romania", "SK": "Slovakia",
    "SI": "Slovenia", "ES": "Spain", "SE": "Sweden", "GB": "United Kingdom", "UK": "United Kingdom",
    "CH": "Switzerland", "NO": "Norway", "IS": "Iceland", "LI": "Liechtenstein",
    "MK": "North Macedonia", "AL": "Albania", "RS": "Serbia", "ME": "Montenegro",
    "BA": "Bosnia and Herzegovina", "MD": "Moldova", "UA": "Ukraine", "TR": "Türkiye",
}


def norm_key(k):
    return re.sub(r"[^a-z0-9]+", " ", str(k).lower()).strip()


def parse_number(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace("\u00a0", "")
    if not s or s.lower() in ("-", "--", ":", "..", "na", "n/a", "null", "none", "nan"):
        return None
    s = re.sub(r"[€$£%]", "", s)
    s = re.sub(r"[A-Za-z]+$", "", s).strip().replace(" ", "")
    if not s:
        return None
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        if re.fullmatch(r"-?\d{1,3}(,\d{3})+", s):
            s = s.replace(",", "")
        else:
            s = s.replace(",", ".")
    try:
        return float(s)
    except ValueError:
        return None


def extract_year(v):
    if v is None:
        return None
    if isinstance(v, (int, float)) and float(v).is_integer():
        y = int(v)
        return y if 1950 <= y <= 2035 else None
    m = re.search(r"(?:19|20)\d{2}", str(v))
    if m:
        y = int(m.group(0))
        return y if 1950 <= y <= 2035 else None
    return None


def clean_country(v):
    if v is None:
        return None
    s = str(v).strip()
    if not s:
        return None
    up = s.upper()
    if up in COUNTRY_CODES:
        return COUNTRY_CODES[up]
    return s


def metric_matches(metric, k):
    if metric == "growth" and ("population" in k or "unemploy" in k):
        return False
    if metric == "gdp" and "per capita" in k:
        return False
    if metric == "debt" and "deficit" in k:
        return False
    if metric == "value" and any(
        x in k for x in ("gdp", "growth", "inflation", "unemploy", "debt", "deficit")
    ):
        return False
    return True


def discover_files():
    found = []
    for base in [os.getcwd()]:
        for root, dirs, files in os.walk(base):
            dirs[:] = [d for d in dirs if d not in EXCLUDE_DIRS and not d.startswith(".")]
            for f in files:
                if f in EXCLUDE_FILES or f.startswith("."):
                    continue
                if f.lower().endswith((".csv", ".tsv", ".txt", ".md", ".json", ".jsonl")):
                    found.append(os.path.join(root, f))
    return sorted(found)


def json_to_rows(obj):
    if isinstance(obj, list):
        return [r for r in obj if isinstance(r, dict)]
    if not isinstance(obj, dict):
        return []
    for k in ("data", "records", "rows", "values", "observations", "result", "series"):
        v = obj.get(k)
        if isinstance(v, list):
            return [r for r in v if isinstance(r, dict)]
    for k, v in obj.items():
        if isinstance(v, dict) and v and all(
            isinstance(x, (int, float, str)) for x in v.values()
        ):
            rows = []
            for t, val in v.items():
                row = {"time": t, "value": val}
                for kk, vv in obj.items():
                    if kk != k and isinstance(vv, (str, int, float)):
                        row[kk] = vv
                rows.append(row)
            return rows
    return [obj]


def md_tables_to_rows(text):
    rows = []
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if line.startswith("|"):
            header = [c.strip() for c in line.strip("|").split("|")]
            j = i + 1
            while j < len(lines) and lines[j].strip().startswith("|"):
                sep = [c.strip() for c in lines[j].strip("|").split("|")]
                if sep and all(re.fullmatch(r":?-{2,}:?", c) for c in sep if c):
                    j += 1
                    continue
                vals = [c.strip() for c in lines[j].strip("|").split("|")]
                if len(vals) == len(header):
                    rows.append(dict(zip(header, vals)))
                j += 1
            i = j
        else:
            i += 1
    return rows


def load_rows(path):
    ext = os.path.splitext(path)[1].lower()
    rows = []
    try:
        if ext == ".json":
            with open(path, encoding="utf-8-sig") as fh:
                obj = json.load(fh)
            rows = json_to_rows(obj)
        elif ext == ".jsonl":
            with open(path, encoding="utf-8-sig") as fh:
                rows = [json.loads(l) for l in fh if l.strip()]
        elif ext in (".csv", ".tsv"):
            with open(path, encoding="utf-8-sig", newline="") as fh:
                sample = fh.read(8192)
                fh.seek(0)
                try:
                    delim = csv.Sniffer().sniff(sample, delimiters=",;\t").delimiter
                except Exception:
                    delim = ";" if ";" in sample else ("," if "," in sample else "\t")
                rd = csv.DictReader(fh, delimiter=delim)
                rows = [dict(r) for r in rd if any((v or "").strip() for v in r.values())]
        elif ext in (".txt", ".md"):
            with open(path, encoding="utf-8-sig") as fh:
                text = fh.read()
            rows = md_tables_to_rows(text)
            if not rows:
                kv = {}
                for line in text.splitlines():
                    if line.lstrip().startswith(("#", "-", "*", ">")):
                        continue
                    m = re.match(r"^\s*([A-Za-z][A-Za-z0-9 _\-/().]*?)\s*[:=]\s*(.+?)\s*$", line)
                    if m:
                        kv[m.group(1).strip()] = m.group(2).strip()
                if kv:
                    rows = [kv]
    except Exception as exc:
        print(f"[warn] could not parse {path}: {exc}")
    return rows


def extract_into(datasets, rows):
    norm_rows = []
    for r in rows:
        nr = {}
        for k, v in r.items():
            if k is None:
                continue
            nr[norm_key(k)] = v
        if nr:
            norm_rows.append(nr)
    if not norm_rows:
        return 0

    all_keys = set()
    for r in norm_rows:
        all_keys.update(r.keys())

    country_key = next((k for k in all_keys if any(kw in k for kw in COUNTRY_KEYS)), None)
    year_key = None
    for k in all_keys:
        if any(kw in k for kw in YEAR_KEYS):
            if any(extract_year(r.get(k)) is not None for r in norm_rows[:80]):
                year_key = k
                break
    indicator_key = next(
        (k for k in all_keys if any(kw in k for kw in INDICATOR_KEYS)), None
    )

    used = 0
    for r in norm_rows:
        country = clean_country(r.get(country_key)) if country_key else None
        year = extract_year(r.get(year_key)) if year_key else None
        contributed = False
        claimed = set()

        # Row-level indicator label (long-format datasets)
        ind_raw = r.get(indicator_key) if indicator_key else None
        ind_metric = None
        if ind_raw is not None:
            iv = norm_key(str(ind_raw))
            for metric, kws in METRICS:
                if any(kw in iv for kw in kws):
                    ind_metric = metric
                    break
        if ind_metric:
            for k, v in r.items():
                if k in (country_key, year_key, indicator_key):
                    continue
                num = parse_number(v)
                if num is not None:
                    datasets[ind_metric].append((country, year, num))
                    claimed.add(k)
                    contributed = True
                    break

        for metric, kws in METRICS:
            for k, v in r.items():
                if k in claimed or k == country_key or k == year_key or k == indicator_key:
                    continue
                if not metric_matches(metric, k) or not any(kw in k for kw in kws):
                    continue
                num = parse_number(v)
                if num is None:
                    continue
                col_year = year
                if col_year is None:
                    m = re.search(r"(?:19|20)\d{2}", k)
                    if m:
                        col_year = int(m.group(0))
                datasets[metric].append((country, col_year, num))
                claimed.add(k)
                contributed = True

        # Wide-by-year tables: bare 4-digit year columns
        for k, v in r.items():
            if k in claimed or k == country_key or k == year_key or k == indicator_key:
                continue
            if re.fullmatch(r"(?:19|20)\d{2}", k):
                num = parse_number(v)
                if num is not None:
                    datasets["value"].append((country, int(k), num))
                    claimed.add(k)
                    contributed = True

        if contributed:
            used += 1
    return used


def member_items(ds, latest_only=True):
    rows = ds
    if latest_only:
        ys = [y for _, y, _ in rows if y is not None]
        if ys:
            ly = max(ys)
            rows = [t for t in rows if t[1] == ly]
    agg = defaultdict(list)
    for c, _, v in rows:
        if c is None:
            continue
        agg[c].append(v)
    items = [(c, statistics.mean(vs)) for c, vs in agg.items()]
    mem = [(c, v) for c, v in items if not AGGREGATE_RE.search(c)]
    if len(mem) >= 2:
        return mem
    return items


def yearly_means(ds):
    by_year = defaultdict(list)
    for c, y, v in ds:
        if y is None or c is None:
            continue
        if AGGREGATE_RE.search(c):
            continue
        by_year[y].append(v)
    return [(y, statistics.mean(by_year[y])) for y in sorted(by_year)]


def series_for(ds, pattern):
    out = defaultdict(list)
    for c, y, v in ds:
        if y is not None and c and re.search(pattern, c, re.I):
            out[y].append(v)
    return [(y, statistics.mean(vs)) for y, vs in sorted(out.items())]


def hbar(title, items, width=24, nd=2):
    mn = min(v for _, v in items)
    mx = max(v for _, v in items)
    scale = max(abs(mn), abs(mx), 1e-9)
    labw = min(max(len(str(l)) for l, _ in items), 24)
    out = [f"**{title}**", "```"]
    for lab, v in items:
        n = int(round(abs(v) / scale * width))
        bar = "#" * n
        if v >= 0:
            out.append(f"{str(lab)[:labw]:<{labw}} |{bar:<{width}}| +{v:,.{nd}f}")
        else:
            out.append(f"{str(lab)[:labw]:<{labw}} |{bar:>{width}}| {v:,.{nd}f}")
    out.append("```")
    return "\n".join(out)


def build_headline(datasets):
    candidates = []
    for metric, unit in [
        ("growth", "percentage points"),
        ("inflation", "percentage points"),
        ("unemployment", "percentage points"),
        ("debt", "points of GDP"),
    ]:
        items = member_items(datasets[metric])
        if len(items) < 2:
            continue
        srt = sorted(items, key=lambda t: t[1])
        low_c, low_v = srt[0]
        high_c, high_v = srt[-1]
        spread = high_v - low_v
        if metric == "growth":
            msg = (f"Europe's growth divide: **{high_c}** expanded {high_v:.1f}% while "
                   f"**{low_c}** grew just {low_v:.1f}% — a {spread:.1f}-point gap.")
        elif metric == "inflation":
            msg = (f"Inflation spans **{low_v:.1f}%** ({low_c}) to **{high_v:.1f}%** ({high_c}) — "
                   f"a {spread:.1f}-point spread around the ECB's 2% target.")
        elif metric == "unemployment":
            msg = (f"Labour markets diverge sharply: unemployment is **{low_v:.1f}%** in {low_c} "
                   f"but **{high_v:.1f}%** in {high_c}.")
        else:
            msg = (f"Public debt tells two Europes: **{high_v:.0f}% of GDP** in {high_c} versus "
                   f"**{low_v:.0f}%** in {low_c} — on opposite sides of the 60% Maastricht reference.")
        candidates.append((abs(spread), msg))
    if candidates:
        return max(candidates, key=lambda t: t[0])[1]
    return ("The local dataset paints a picture of a resilient but uneven European economy — "
            "the sections below show where the risks and opportunities lie.")


def write_report(datasets, sources):
    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    total_obs = sum(len(ds) for ds in datasets.values())
    lines = []

